@criterion(description='Compiling a fresh release in which many products carry a quota_cap with the delivered tool.zip gives the contract quota for every active product in profile_prod.json.')
def prod_quota_capped(workspace: Path) -> bool:
    return _holds(_check_quota, 'capped', 'profile_prod.json')


@criterion(description='Compiling a fresh release from a read-only renamed input folder as another user gives the contract config.json.')
def readonly_inputs(workspace: Path) -> bool:
    return _holds(_check_read_only)


@criterion(description='Every document the delivered tool.zip writes for a fresh release is JSON with two-space indent, sorted keys and one trailing newline.')
def document_format(workspace: Path) -> bool:
    return _holds(_check_format)


@criterion(description='The delivered /app/out/tool.zip holds cli.py at its root.')
def tool_zip_layout(workspace: Path) -> bool:
    return _holds(_check_layout)


@criterion(description='The delivered tool.zip writes the shipped release name into config.json for a fresh release with another name.')
def negative_hardcoded_sample_answers(workspace: Path) -> bool:
    return _holds(_check_restates_shipped)


